parameters.message:
An application arrived and was saved to the Applications sheet, but the AI screening step failed, so it has no score yet. Read it in the sheet and screen it manually — do not let it sit unscored.

Name: {{ $('Normalise Application').first().json.applicant_name }}
Email: {{ $('Normalise Application').first().json.email }}
Role: {{ $('Normalise Application').first().json.role }}
Error: {{ $json.error.message }}

Common causes: an expired or out-of-credit OpenAI API key. Fix the key and re-run the screening by hand if needed.

parameters.jsCode:
// Safe parse of the AI screening reply. If the AI returns anything
// unexpected, fall back to an explicit "unscored" result instead of
// crashing — the application is already saved in the sheet either way,
// and a human reads every application before any decision.
let parsed = null;
try {
  const raw = $input.first().json.choices[0].message.content;
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}
if (!parsed || typeof parsed !== 'object') {
  parsed = { score: 0, verdict: 'unscored', summary: 'AI screening failed — read the application in the sheet.', strengths: [], gaps: [] };
}
let score = parseInt(parsed.score, 10);
if (isNaN(score)) score = 0;
score = Math.max(0, Math.min(10, score));
const verdicts = ['shortlist', 'maybe', 'pass', 'unscored'];
let verdict = String(parsed.verdict || '').toLowerCase().trim();
if (!verdicts.includes(verdict)) verdict = score === 0 ? 'unscored' : 'maybe';
const asList = (v) => Array.isArray(v) ? v.map(x => String(x)) : (v ? [String(v)] : []);
return [{ json: {
  score: score,
  verdict: verdict,
  summary: String(parsed.summary || ''),
  strengths: asList(parsed.strengths),
  gaps: asList(parsed.gaps)
} }];

